contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint _val) public {
        bool revertedSetMinSum;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertedSetMinSum = true; } else { revertedSetMinSum = false; }

        uint minSumAfterSet = c.MinSum(); if (__ESBMC_reverted()) return;

        bool revertedInitialized;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { revertedInitialized = true; } else { revertedInitialized = false; }

        uint minSumAfterInit = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(!revertedSetMinSum && minSumAfterSet == _val && !revertedInitialized && minSumAfterInit == _val);
    }
}

