// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 _val) internal {
        bool revertedSetMinSum;
        try c.SetMinSum(_val) { revertedSetMinSum = false; } catch { revertedSetMinSum = true; }
        uint256 minSumAfterSet;
        try c.MinSum() returns (uint256 __r) { minSumAfterSet = __r; } catch { return; }
        bool revertedInitialized;
        try c.Initialized() { revertedInitialized = false; } catch { revertedInitialized = true; }
        uint256 minSumAfterInit;
        try c.MinSum() returns (uint256 __r) { minSumAfterInit = __r; } catch { return; }
        assertTrue(!revertedSetMinSum && minSumAfterSet == _val && !revertedInitialized && minSumAfterInit == _val);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
